"use strict";

// The rows ARE the requirement: which shows each filter keeps. verify() runs
// the shipped rule over three shows chosen so each row's answer can only come
// from the filter it names.
const TABLE = {
  columns: ["Filter", "Kept"],
  rows: [
    ["None", "every show"],
    ["A tag required", "only the shows filed under it"],
    ["Two tags required", "the shows filed under either"],
    ["A tag ruled out", "every show not filed under it"],
    ["A tag both required and ruled out on one show", "not that show: ruled out wins"],
    ["A festival left out", "none of that festival's shows"],
  ],
};

const SHOWS = [
  { slug: "haifa-iff/a", genreSlugs: ["haifa-iff/competition"] },
  { slug: "haifa-iff/b", genreSlugs: ["haifa-iff/panorama", "haifa-iff/family"] },
  { slug: "acco/c", genreSlugs: ["acco/premiere"] },
];

module.exports = {
  description: "a required tag keeps its shows, a ruled-out tag drops its shows, a festival left out drops all of them",
  table: TABLE,
  async verify(assert) {
    const { passesFilters } = await import("../../../../site/planNG/lib/filters.js");
    const kept = (filters) => SHOWS.filter((show) => passesFilters(show, filters)).map((s) => s.slug);

    assert.deepEqual(kept({}), ["haifa-iff/a", "haifa-iff/b", "acco/c"], "no filter keeps every show");
    assert.deepEqual(
      kept({ tags: new Map([["haifa-iff/competition", "only"]]) }),
      ["haifa-iff/a"],
      "a required tag keeps only its shows, whichever festival the rest are from"
    );
    assert.deepEqual(
      kept({ tags: new Map([["haifa-iff/competition", "only"], ["acco/premiere", "only"]]) }),
      ["haifa-iff/a", "acco/c"],
      "two required tags keep the shows under either"
    );
    assert.deepEqual(
      kept({ tags: new Map([["haifa-iff/family", "out"]]) }),
      ["haifa-iff/a", "acco/c"],
      "a ruled-out tag drops only its shows"
    );
    assert.deepEqual(
      kept({ tags: new Map([["haifa-iff/panorama", "only"], ["haifa-iff/family", "out"]]) }),
      [],
      "ruled out wins over required on the same show"
    );
    assert.deepEqual(
      kept({ festivalsOut: new Set(["acco"]) }),
      ["haifa-iff/a", "haifa-iff/b"],
      "a festival left out drops all its shows"
    );
  },
};
"use strict";

// The rows ARE the requirement: what a show with no published length is
// allowed near the day's end and the reader's own blocks.
const TABLE = {
  columns: ["A show with no length, starting", "Day ends 20:30", "Dinner 21:00–22:00"],
  rows: [
    ["19:30", "drafted: an hour ends at 20:30", "drafted"],
    ["20:00", "not drafted: an hour runs past 20:30", "drafted: it ends as dinner starts"],
    ["20:30", "not drafted", "not drafted: it runs into dinner"],
  ],
};

const show = (id, start) => ({
  slug: `acco/${id}`,
  title: id,
  venue: "v",
  duration: null,
  performances: [{ date: "2026-09-29", start, status: "AVAILABLE" }],
});

module.exports = {
  description: "a show with no published length counts as an hour against the day's end and the reader's blocks",
  table: TABLE,
  async verify(assert) {
    const { draftCalendar } = await import("../../../../site/plan/lib/contention.js");
    const { ASSUMED_LENGTH_MIN, slotRule } = await import("../../../../site/planNG/lib/days.js");
    assert.equal(ASSUMED_LENGTH_MIN, 60, "an hour");
    const base = {
      dateStart: "2026-09-29",
      dateEnd: "2026-09-29",
      windowStart: "2026-09-29T00:00",
      windowEnd: "2026-09-29T23:59",
      assumedLengthMin: ASSUMED_LENGTH_MIN,
    };
    const drafted = (start, opts) =>
      draftCalendar([show("x", start)], { ...base, ...opts }).days.flatMap((d) => d.slots).length === 1;

    assert.equal(drafted("19:30", { dayEndMin: 20 * 60 + 30 }), true, "19:30 plus an hour fits a 20:30 end");
    assert.equal(drafted("20:00", { dayEndMin: 20 * 60 + 30 }), false, "20:00 plus an hour does not");
    const dinner = slotRule(new Map(), new Map([["2026-09-29", [{ startMin: 21 * 60, endMin: 22 * 60 }]]]));
    assert.equal(drafted("20:30", { dayEndMin: 20 * 60 + 30 }), false, "nor does 20:30");
    const withDinner = (start) => drafted(start, { dayEndMin: 25 * 60, allowSlot: dinner });
    assert.equal(withDinner("19:30"), true, "well before dinner");
    assert.equal(withDinner("20:00"), true, "ending as dinner starts is fine");
    assert.equal(withDinner("20:30"), false, "running into dinner is not");
  },
};
